(* [comment removed for export] *)
Definition fsm5_fp (fs pos ff : Z) (col : Z -> Z -> Prop) (a : Z) : Prop :=
  (fs + 40 <= a < fs + 40 + 8)%Z \/ a = (fs + 96)%Z \/ a = gc_fl fs CLS pos \/ (ff + 24 <= a < ff + 32)%Z \/ (ff + 2040 <= a < ff + 2040 + 8)%Z
  \/ (SB + ff / 8 <= a < SB + ff / 8 + 256)%Z
  \/ (exists c i, gc_valid c i /\ col c i /\ (a = gc_fl fs c i \/ gc_insh fs c i a)).
(* [comment removed for export] *)
Definition fsm5_post (gb : Z) (mem0 Mf : word -> option byte) (lo hi s fs h j pos ff : Z) (col : Z -> Z -> Prop) : Prop :=
  mem_grows mem0 Mf
  /\ (forall x : word, (bv_unsigned x < lo \/ hi <= bv_unsigned x)%Z -> ~ fsm5_fp fs pos ff col (bv_unsigned x) -> Mf x = mem0 x)
  /\ rdn ASEGS Mf (Z_to_bv 64 (fs + 40)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 (h + j + 1)))                       (* [comment removed for export] *)
  /\ rdn ASEGS Mf (Z_to_bv 64 (fs + 96)) 1%nat = Some [Z_to_bv 8 gb]                                                   (* [comment removed for export] *)
  /\ rdn ASEGS Mf (Z_to_bv 64 (gc_fl fs CLS pos)) 1%nat = Some [Z_to_bv 8 1]                                            (* [comment removed for export] *)
  /\ (forall c i, gc_valid c i -> col c i -> ~ (c = CLS /\ i = pos) -> rdn ASEGS Mf (Z_to_bv 64 (gc_fl fs c i)) 1%nat = Some [Z_to_bv 8 0])   (* [comment removed for export] *)
  /\ rdn ASEGS Mf (Z_to_bv 64 (ff + 24)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 s))                               (* [comment removed for export] *)
  /\ rdn ASEGS Mf (Z_to_bv 64 (ff + 2040)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 (gc_fl fs CLS pos)))             (* [comment removed for export] *)
  /\ (forall i, (0 <= i < 256)%Z -> Mf (Z_to_bv 64 (SB + ff / 8 + i)) = Some (Z_to_bv 8 0)).                             (* [comment removed for export] *)

Section POST5.
  Variables mem0 Mg : word -> option byte.
  Variables gb lo hi s fs h j pos ff : Z.
  Variable col : Z -> Z -> Prop.
  Hypothesis GP : gc_postb gb mem0 Mg lo hi fs col.
  Hypothesis Hfs : (0x6c4000 <= fs)%Z /\ (fs + 4096 + 32768 + 11 * 2 ^ 20 < 2 ^ 47)%Z.
  Hypothesis Happm : (fs + 4096 + 32768 + 11 * 2 ^ 20 <= 0x7fff7000 \/ 0x10007fff8000 <= fs)%Z.
  Hypothesis Hpos : (0 <= pos < 512)%Z.
  Hypothesis Hff_def : ff = (fs + 4096 + 32768 + 5242880 + 2048 * pos)%Z.

  #[local] Ltac pw e := let v := eval vm_compute in e in change e with v.
  #[local] Ltac pwin e H := let v := eval vm_compute in e in change e with v in H.
  #[local] Ltac lens := rewrite ?length_N_to_le_bytes; cbn [length Z.of_nat Pos.to_nat].
  #[local] Ltac side := lens; rewrite ?u64_lit by lia; lia.
  #[local] Ltac peel_pt := repeat (rewrite wbytes_outside by side).
  #[local] Ltac peel_rd := repeat (rewrite rdn_wbytes_out by side).

  Lemma le8_zero_p : word_to_le_bytes 8 (Z_to_bv 64 0) = repeat (Z_to_bv 8 0) 8.
  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SD0|30;!1,20!1+11!1+>2!1,C2!3,^V1,:!2'^W1,:!1,D2!3,C256!3,C257!3,C258!3,C259!3,C25:!3,C25;!3,C25<!1+1#1!1+1#2%~R!3+9!1+1#3#2#1!3+9+0!2'7#4#3!2'7#4#2%~R!3+9+0!2'7#3#2!2'7#3#1!3+9!1+1#4#3#2&H;R$n;R+^X$b1;R>$b2;R?!5'^Y@A%~R!3+9+0!2'7#3#2!2'7#3#1!3+9!1+1#4#3#2$~R@$~R%~R!3+9+0!2'7#4#3!2'7#4#2!3+9!1+1#5#4#3#1!3'^Z#3#2#1%n;R+^X%b1;R>%b2;R?A!4#1155!2,V+0!2'715}8vv!:'^U233455==B!:'^U233455<<B!:'^U233455;;B!:'^U233455::B!:'^U23345599B!:'^U23345588B!:'^U23345577B!:'^U23345566B!2,V36!3+93!2'^[C!2'A!1,2|600;,:!3'^\2!2'A1,:C").
